type GenericConstructor<T> = new (...args: any[]) => T;
export type KlassConstructor<Cls extends GenericConstructor<any>> =
  GenericConstructor<InstanceType<Cls>> & {[k in keyof Cls]: Cls[k]};
export type Klass<T extends LexicalNode> = InstanceType<T['constructor']> extends T
  ? T['constructor']
  : GenericConstructor<T> & T['constructor'];
export declare class LexicalNode {
  ['constructor']: KlassConstructor<typeof LexicalNode>;
  static clone(node: LexicalNode): LexicalNode;
}
export declare class ListNode extends LexicalNode {
  static clone(node: ListNode): ListNode;
  getListType(): string;
}
export declare function $nodesOfType<T extends LexicalNode>(klass: Klass<T>): Array<T>;
export declare function registerNodeTransform<T extends LexicalNode>(
  klass: Klass<T>,
  listener: (node: T) => void,
): void;
